  const field = kind === "questions" ? "questionActualMinutes" : "studyActualMinutes";
  const label = kind === "questions" ? "questões" : "estudo teórico";
  const minutes = Number(prompt(`Quantos minutos de ${label} foram feitos?`, 0));
